-- ============================================================
-- Migration 039 — Registra los 43 skills de competencia faltantes de Pre-Producción
-- (nodos 3.1-3.21) en forge_skill_configs. Complementa la 038.
-- El r2_path apunta a  skills/<key>.md  en el bucket forge-system-prompts.
-- CONVENCIÓN: subir cada .md a ese bucket ANTES de que el nodo lo use.
-- Fuente: _PreProd 0707/skills_faltantes_R2/.  Idempotente: ON CONFLICT (key) DO UPDATE.
-- ============================================================

ON CONFLICT (key) DO UPDATE SET
  r2_path     = EXCLUDED.r2_path,
  description = EXCLUDED.description,
  updated_at  = now();
